import sqlite3

def ajouter_produit(nom, prix, stock):
    conn = None
    try:
        conn = sqlite3.connect('produits.db')
        cursor = conn.cursor()
        cursor.execute(
            'INSERT INTO PRODUIT (nom, prix, stock) VALUES (?, ?, ?)',
            (nom, prix, stock)
        )
        conn.commit()
        print("Produit ajouté")
        return True
    except sqlite3.Error as e:
        print(f"Erreur lors de l'ajout: {e}")
        if conn:
            conn.rollback()
        return False
    finally:
        if conn:
            conn.close()

def get_produit_par_nom(nom):
    conn = None
    try:
        conn = sqlite3.connect('produits.db')
        cursor = conn.cursor()
        cursor.execute(
            'SELECT * FROM PRODUIT WHERE nom = ?',
            (nom,)
        )
        return cursor.fetchone()
    except sqlite3.Error as e:
        print(f"Erreur lors de la recherche: {e}")
        return None
    finally:
        if conn:
            conn.close()
